// HI11 B; generated by hi11_gen.py. Board observations pending.
module top(input clk_25mhz, output ftdi_rxd);
  reg loadn=1, move=0, direction=1;
  wire flag;
  reg [15:0] warm=0;
  reg run=0;
  reg [11:0] u=0;
  always @(posedge clk_25mhz) begin
    if (!run) begin
      warm<=warm+1'b1;
      if (&warm) run<=1;
    end else if (u<2048) u<=u+1'b1;
  end
  always @(posedge clk_25mhz) if (run) begin
    if (u < 16) begin loadn<=1'b1; move<=(0); direction<=1'b1; end
    else if (u < 48) begin loadn<=1'b1; move<=(u[1:0] == 0); direction<=1'b1; end
    else if (u < 52) begin loadn<=1'b1; move<=(0); direction<=1'b0; end
    else if (u < 56) begin loadn<=1'b1; move<=(0); direction<=1'b1; end
    else if (u < 60) begin loadn<=1'b0; move<=(0); direction<=1'b0; end
    else if (u < 64) begin loadn<=1'b1; move<=(0); direction<=1'b0; end
    else if (u < 624) begin loadn<=1'b1; move<=(u[1:0] == 0); direction<=1'b0; end
    else if (u < 628) begin loadn<=1'b0; move<=(0); direction<=1'b1; end
    else if (u < 632) begin loadn<=1'b1; move<=(0); direction<=1'b1; end
    else if (u < 1192) begin loadn<=1'b1; move<=(u[1:0] == 0); direction<=1'b1; end
    else if (u < 1200) begin loadn<=1'b1; move<=(0); direction<=1'b0; end
    else if (u < 1208) begin loadn<=1'b1; move<=(0); direction<=1'b1; end
    else if (u < 1212) begin loadn<=1'b0; move<=(0); direction<=1'b0; end
    else if (u < 1216) begin loadn<=1'b1; move<=(0); direction<=1'b0; end
    else if (u < 1248) begin loadn<=1'b1; move<=(1); direction<=1'b0; end
    else if (u < 1256) begin loadn<=1'b1; move<=(0); direction<=1'b0; end
    else if (u < 1260) begin loadn<=1'b1; move<=(0); direction<=1'b1; end
    else if (u < 1292) begin loadn<=1'b1; move<=(1); direction<=1'b1; end
    else if (u < 1300) begin loadn<=1'b1; move<=(0); direction<=1'b1; end
    else if (u < 1304) begin loadn<=1'b0; move<=(0); direction<=1'b0; end
    else if (u < 1308) begin loadn<=1'b1; move<=(0); direction<=1'b0; end
    else if (u < 1388) begin loadn<=1'b1; move<=(u[1] == 0); direction<=1'b0; end
    else if (u < 1420) begin loadn<=1'b0; move<=(u[1] == 0); direction<=1'b0; end
    else if (u < 2048) begin loadn<=1'b1; move<=(0); direction<=1'b0; end
  end
  // Capture stable controls/CFLAG before this edge updates the controls.
  reg [3:0] record [0:2047];
  reg [3:0] checksum=0;
  wire [3:0] sample={loadn,move,direction,flag};
  always @(posedge clk_25mhz) if (run && u<2048) begin
    record[u[10:0]]<=sample;
    checksum<=checksum^sample;
  end
  wire done=u==2048;
  function [7:0] hex(input [3:0] v);
    hex=v<10 ? 8'h30+v : 8'h37+v;
  endfunction
  // H11B, eight sequence digits, 2048 sample nibbles, XOR nibble, CR LF.
  reg [31:0] sequence_number=0;
  reg [11:0] ci=0;
  wire [10:0] read_address=ci-12;
  reg [3:0] read_sample=0;
  always @(posedge clk_25mhz) read_sample<=record[read_address];
  reg [7:0] ch;
  always @* begin
    if (ci==0) ch="H";
    else if (ci==1 || ci==2) ch="1";
    else if (ci==3) ch="B";
    else if (ci<12) ch=hex(sequence_number[31-4*(ci-4) -: 4]);
    else if (ci<2060) ch=hex(read_sample);
    else if (ci==2060) ch=hex(checksum);
    else if (ci==2061) ch=8'h0d;
    else ch=8'h0a;
  end
  (* syn_useioff=0 *) reg tx=1;
  reg busy=0;
  reg [7:0] baud=0;
  reg [3:0] bitn=0;
  reg [9:0] shift=10'h3ff;
  reg [22:0] pause=0;
  reg [1:0] gap=2;
  always @(posedge clk_25mhz)
    if (!busy) begin
      if (pause!=0) pause<=pause-1'b1;
      else if (gap!=0) gap<=gap-1'b1;
      else if (done) begin
        shift<={1'b1,ch,1'b0};
        busy<=1; baud<=0; bitn<=0;
      end
    end else if (baud==216) begin
      baud<=0; tx<=shift[0]; shift<={1'b1,shift[9:1]}; bitn<=bitn+1'b1;
      if (bitn==9) begin
        busy<=0; gap<=2; // Allow the synchronous record read to settle.
        if (ci==2062) begin
          ci<=0; sequence_number<=sequence_number+1'b1; pause<=23'd2500000;
        end else ci<=ci+1'b1;
      end
    end else baud<=baud+1'b1;
  (* syn_useioff=0 *) reg registered_tx=1;
  always @(posedge clk_25mhz) registered_tx<=tx;
  DELAYG #(.DEL_MODE("USER_DEFINED"), .DEL_VALUE(127)) tx_delay(
    .A(registered_tx), .Z(ftdi_rxd));
  assign flag=0;
endmodule
